    async create(dto: CreateLegionDto, icon): Promise<Legion> {
        const legionIconPath = await this.fileService.uploadFile(icon);


        const legion = await this.legionModel.create({
            ...dto,
            planets: [],
            icon: legionIconPath
        })

        return legion
