                    return { id: null };
                }
                return await this.delete(legion.id);
            }))
            return deletedIds;
        } catch (error) {
            handleGeneralServerError(error)
        }
    }


    async update(id: string, dto: UpdateLegionDto, icon: Express.Multer.File | null): Promise<Legion | null> {
