                        'icon': iconPath,
                    }
                }
                , { new: true, runValidators: true }
            )
            handleObjNotFound(updatedLegion, id)
            if (icon && legion.icon) {
                await this.fileService.deleteFile(legion.icon);
            }
            return updatedLegion;
        } catch (error) {
            handleGeneralServerError(error);
        }
    }


